tests:
def test_valid_simple():
    assert is_valid_parentheses('()') is True
    assert is_valid_parentheses('()[]{}') is True


def test_valid_nested():
    assert is_valid_parentheses('{[()]}') is True


def test_invalid_mismatched():
    assert is_valid_parentheses('(]') is False
    assert is_valid_parentheses('([)]') is False


def test_invalid_unclosed():
    assert is_valid_parentheses('(') is False
